import{_ as r}from"./chunks/backup.C75kiyfA.js";import{_ as e,o as t,c as o,a2 as l}from"./chunks/framework.DSc8fo6x.js";const b=JSON.parse('{"title":"Бэкап и восстановление","description":"","frontmatter":{},"headers":[],"relativePath":"ru/backup.md","filePath":"ru/backup.md"}'),n={name:"ru/backup.md"};function s(i,a,h,d,g,p){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="бэкап-и-восстановление" tabindex="-1">Бэкап и восстановление <a class="header-anchor" href="#бэкап-и-восстановление" aria-label="Permalink to &quot;Бэкап и восстановление&quot;">​</a></h1><p><img src="'+r+'" alt="Бэкап"></p><h2 id="программа-сама-делает-бэкап" tabindex="-1">Программа сама делает бэкап <a class="header-anchor" href="#программа-сама-делает-бэкап" aria-label="Permalink to &quot;Программа сама делает бэкап&quot;">​</a></h2><ul><li>Регулярно (обычно раз в 20 часов) и <strong>при закрытии</strong>.</li><li>Отдельный бэкап перед обновлением и перед восстановлением.</li><li>Если подключён <a href="./telegram.html">Telegram</a> — раз в день на телефон.</li></ul><h2 id="раз-в-неделю-usb" tabindex="-1">Раз в неделю: USB <a class="header-anchor" href="#раз-в-неделю-usb" aria-label="Permalink to &quot;Раз в неделю: USB&quot;">​</a></h2><p>Вставьте USB-флешку → <strong>Бэкап</strong> → <strong>Скопировать последний бэкап на диск …</strong>. Не храните флешку рядом с компьютером.</p><h2 id="код-восстановления" tabindex="-1">Код восстановления <a class="header-anchor" href="#код-восстановления" aria-label="Permalink to &quot;Код восстановления&quot;">​</a></h2><p><strong>Бэкап → Код восстановления</strong> → ваш пароль. Его нужно записать на бумаге — если компьютер сломается, без него данные не вернуть.</p><h2 id="восстановить-бэкап" tabindex="-1">Восстановить бэкап <a class="header-anchor" href="#восстановить-бэкап" aria-label="Permalink to &quot;Восстановить бэкап&quot;">​</a></h2><p>Если что-то случайно испортилось:</p><ul><li>в списке рядом с бэкапом <strong>Восстановить</strong> → пароль админа.</li></ul><h3 id="fayldan-berpa" tabindex="-1">Восстановление из файла <a class="header-anchor" href="#fayldan-berpa" aria-label="Permalink to &quot;Восстановление из файла {#fayldan-berpa}&quot;">​</a></h3><p>Файл с USB или скачанный из Telegram: <strong>Восстановить из файла</strong> → выберите файл → пароль админа.</p><ul><li><strong>Если из Telegram пришли части (<code>.001</code>, <code>.002</code>…)</strong> — скачайте все и выберите <strong>все вместе</strong> (с Ctrl).</li><li>Если файл с другого компьютера — введите и <strong>код восстановления</strong> той установки.</li></ul><p>После восстановления все входят заново. Состояние до восстановления остаётся как бэкап «Перед восстановлением» — ничего не теряется.</p><h2 id="berpa-ekrani" tabindex="-1">Экран восстановления <a class="header-anchor" href="#berpa-ekrani" aria-label="Permalink to &quot;Экран восстановления {#berpa-ekrani}&quot;">​</a></h2><p>Если база удалена, повреждена, потерян ключ или осталась старая версия программы, вместо обычного экрана открывается экран <strong>Восстановление</strong>. Причина написана вверху.</p><ol><li>Введите <strong>код восстановления</strong> (с бумаги).</li><li>Выберите: <strong>Восстановить этот бэкап</strong>, <strong>Восстановить из файла</strong> (USB, Telegram), <strong>Восстановить ключ</strong> или <strong>Проверить снова</strong>.</li><li><strong>Начать с пустой базы</strong> — только если бэкапов нет совсем.</li></ol><p>Без кода восстановления на этом экране ничего сделать нельзя — данные защищены. Если написано «Старая версия программы» — просто установите последнюю версию.</p><h2 id="«внимание-база-заменена-старои-копиеи-»" tabindex="-1">«ВНИМАНИЕ: база заменена старой копией!» <a class="header-anchor" href="#«внимание-база-заменена-старои-копиеи-»" aria-label="Permalink to &quot;«ВНИМАНИЕ: база заменена старой копией!»&quot;">​</a></h2><p>Пока программа была закрыта, кто-то заменил файл данных старой копией — продажи за это время могли пропасть. Проверьте бэкапы в Telegram и на USB, при необходимости восстановите более новый, затем <strong>Понятно</strong>.</p><h2 id="komputer-xarab-oldu" tabindex="-1">Компьютер сломался <a class="header-anchor" href="#komputer-xarab-oldu" aria-label="Permalink to &quot;Компьютер сломался {#komputer-xarab-oldu}&quot;">​</a></h2><p>Установите Kassa на новом компьютере → при первом запуске создайте временного админа → <strong>Бэкап → Восстановить из файла</strong> (файл с USB или из Telegram) + <strong>код восстановления</strong> старой установки. Старые пользователи, товары и настройки вернутся.</p>',23)])])}const m=e(n,[["render",s]]);export{b as __pageData,m as default};
